const DARK_MODE_FILTER_LOGO_IDS = new Set([
  "common-room",
  "github",
  "intercom",
  "linear",
  "netlify",
  "sentry",
  "sigma",
  "vercel",
  "x",
]);

export function mcpIntegrationLogoNeedsDarkModeFilter(id: string): boolean {
  return DARK_MODE_FILTER_LOGO_IDS.has(id);
}

export function mcpIntegrationLogo(id: string): string {
  const logo = LOGOS[id as keyof typeof LOGOS];
  if (!logo) return "";
  return `data:${logo.mime};base64,${logo.data}`;
}
